// One namespace for all three packages, so the builds stay true copies of each other. Firefox
// must have browser.* - its chrome.* is callback-only while these calls are promise-returning -
// and Chrome has no browser at all. Safari provides both and works either way.
const api = typeof browser !== "undefined" ? browser : chrome

// Two WebKit quirks are worth naming once: canvas 2D filters sit behind a flag that has never
// shipped enabled, and getBoundingClientRect reports LAYOUT pixels inside a CSS zoom while
// clientX/clientY report rendered ones. Every browser on iOS is WebKit, so this is the engine,
// not the brand.
//
// GestureEvent is WebKit-only and reading it allocates nothing. What this replaces built a node
// to measure - a willReadFrequently canvas in one case - inside the edit frame's own document,
// which is what stopped WebKit compositing a canvas thousands of rows tall below a fixed line on
// iPad. A capability question must never cost a DOM mutation.
function isWebKit() {
    if (typeof GestureEvent !== "undefined") return true

    const ua = navigator.userAgent
    return /AppleWebKit/.test(ua) && !/Chrome|Chromium/.test(ua)
}

