let auto = false
let autocache = false
let autoError = false
let minImageSize = 200
let browserZoom = 1
let targetLang = "en"
let credits = 999999
let contextMenuPos = null
let takeScreenshot = false
let screencropping = false
let hasContextMenu = true
let contextMenuTargetElement = null
let sentLogin = false
let _isEditing = false
let originalBodyOverflow = ""
let originalHtmlOverflow = ""

// Taps are wired on click, never pointerup (commit 7c9be14 swept the other way and this is the
// walk-back): a tap dispatches click ~230ms later and re-hit-tests it, so acting on pointerup
// tears the target out from under its own pending click, which then lands on the page behind.
// Only gesture ends - drag/slider/peek - stay on pointerup.
function lockBodyScroll() {
    originalBodyOverflow = document.body.style.overflow
    originalHtmlOverflow = document.documentElement.style.overflow
    document.body.style.overflow = "hidden"
    document.documentElement.style.overflow = "hidden"
}

function unlockBodyScroll() {
    document.body.style.overflow = originalBodyOverflow
    document.documentElement.style.overflow = originalHtmlOverflow
}

Object.defineProperty(window, 'isEditing', {
    get() {
        return _isEditing
    },
    set(val) {
        if (_isEditing === val) return
        _isEditing = val
        if (_isEditing) {
            lockBodyScroll()
        } else {
            unlockBodyScroll()
        }
    },
    configurable: true
})
