yomiStyle.rel = "stylesheet"
yomiStyle.href = api.runtime.getURL("css/content.css")

const tailwindStyle = document.createElement("link")
tailwindStyle.rel = "stylesheet"
tailwindStyle.href = api.runtime.getURL("css/tailwind.css")

