const yomiOverlay = document.createElement("div")
yomiOverlay.id = "yomi-extension-overlay"
yomiOverlay.style.setProperty("display", "block", "important")
yomiOverlay.style.setProperty("position", "static", "important")
yomiOverlay.style.setProperty("visibility", "visible", "important")
yomiOverlay.style.setProperty("opacity", "1", "important")
yomiOverlay.style.setProperty("z-index", "2147483647", "important")

const yomiDOM = yomiOverlay.attachShadow({ mode: "open" })
// Set while edit mode is open. The frame covers the viewport, so anything that would otherwise
// be appended to the shadow root has to go in here instead to be visible at all.
let yomiEditDoc = null
// Sites that declare a fixed-width viewport (e-hentai ships `width=750`) are laid out at that
// width and scaled down to fit the screen, dragging our injected UI down with them - there is no
// way to opt a subtree out. Counter-scale by the same factor so Yomi renders at its native size.
// On a responsive site the ratio is 1 and every rule keyed off it is inert.
let yomiScale = 1
// Set when the scale changes, cleared by the next observer pass. Every .yomi is positioned by
// dividing page coordinates out of the zoomed space, so a new scale invalidates offsets written
// under the old one - but placeYomi() only ever runs when the TARGET's rect changes, and a
// scale change can leave every target exactly where it was. Rotating the phone on a site that
// declares a fixed-width viewport does precisely that: the layout width is pinned, so nothing
// moves, while screen.width does.
let yomiScaleDirty = false

function measureYomiScale() {
    if (!isMobile()) return 1

    const layoutWidth = document.documentElement.clientWidth
    const deviceWidth = window.screen.width
    if (!layoutWidth || !deviceWidth) return 1

    // Below 1 when a site declares a viewport narrower than the screen and the browser blows the
    // page up to fit - the same distortion, in the other direction, and just as worth undoing.
    return Math.min(4, Math.max(0.5, layoutWidth / deviceWidth))
}

// What is on screen right now, in the layout viewport's own pixels. documentElement.clientWidth
// /clientHeight report the LAYOUT viewport, which by definition does not move when the page is
// pinch-zoomed and does not shrink when a mobile toolbar slides in - so the frame came out
// shorter than the screen on iOS and, once the page was pinched, magnified past its edges.
// visualViewport is the only measure that tracks either.
function getVisibleViewport() {
    const vv = window.visualViewport
    if (vv && vv.width > 0 && vv.height > 0) {
        return { width: vv.width, height: vv.height, left: vv.offsetLeft || 0, top: vv.offsetTop || 0 }
    }
    return {
        width: document.documentElement.clientWidth,
        height: document.documentElement.clientHeight,
        left: 0,
        top: 0
    }
}

// A software keyboard shrinks the visual viewport exactly the way a browser toolbar does, and
// nothing in the measurement can tell the two apart - so the frame followed the keyboard down
// and the editor lost half its height mid-word. A keyboard is meant to sit OVER the page, so
// the frame is frozen while a field inside it has focus and picks the geometry back up on blur,
// which dismissing the keyboard fires a resize for.
//
// Frozen whole rather than just its height: iOS also scrolls the page to reveal the field, which
// moves offsetTop, and a frame that kept following that would drift out from under the keyboard
// instead of staying put beneath it.
function isEditFieldFocused() {
    const active = yomiEditDoc?.activeElement
    if (!active) return false

    const tag = active.tagName?.toLowerCase()
    return tag === "input" || tag === "textarea" || active.isContentEditable === true
}

// The frame lays out at its own CSS size and is blown back up by the transform, so that size is
// the viewport Tailwind's breakpoints inside it read - keep it at the device's own width, and
// let the transform absorb whatever the page's scaling and the user's pinch are doing.
let lastSizedViewportWidth = null

function applyEditFrameSize(frame) {
    const view = getVisibleViewport()
    const target = (isMobile() && window.screen.width) || view.width
    if (!view.width || !target) return

    lastSizedViewportWidth = Math.round(view.width)
    const scale = view.width / target

    frame.style.width = `${Math.round(target)}px`
    frame.style.height = `${Math.round(view.height / scale)}px`
    frame.style.left = `${view.left}px`
    frame.style.top = `${view.top}px`
    // scale(1) is not free: it still promotes the frame to its own compositing layer, and a
    // canvas several thousand rows tall inside one is where WebKit stops compositing the lower
    // part - the bitmap keeps every pixel (getImageData reads row 15900 back fine) but nothing
    // below the cut is ever shown. No transform at all when there is nothing to scale.
    frame.style.transform = Math.abs(scale - 1) < 0.001 ? "" : `scale(${scale})`
}

let editFrameSettleTimer = null

function sizeEditFrame(frame, force = false) {
    if (!frame) return

    // The freeze below exists for one thing: a software keyboard shrinking the viewport while a
    // field is focused. Three cases can never be that, and freezing through them was wrong rather
    // than merely cautious - a rotation with the keyboard up left the frame at its old geometry.
    //   - a desktop has no software keyboard at all
    //   - a keyboard never changes viewport WIDTH
    //   - `force` is the rotation, which is a resize by definition
    const view = getVisibleViewport()
    const widthChanged = lastSizedViewportWidth !== null && Math.round(view.width) !== lastSizedViewportWidth

    if (!force && !widthChanged && isMobile() && isEditFieldFocused()) return

    // A keyboard sliding away reports a different viewport height on every frame of its
    // animation, and the blur that releases the freeze above lands at the START of it - so
    // sizing on each event walked the frame back up in visible steps. Wait for the viewport to
    // stop moving and size once. Desktop stays immediate, where a drag-resize wants to track
    // the pointer, and so does the first sizing, where there is nothing on screen yet to jump.
    if (!isMobile() || !frame.style.height) {
        applyEditFrameSize(frame)
        return
    }

    clearTimeout(editFrameSettleTimer)
    editFrameSettleTimer = setTimeout(() => applyEditFrameSize(frame), 250)
}

function refreshYomiScale(force = false) {
    const previousScale = yomiScale
    yomiScale = measureYomiScale()
    yomiOverlay.style.setProperty("--yomi-scale", yomiScale)
    window.yomiScale = yomiScale

    // A flag rather than repositioning from here: this runs at module top level, where the
    // observer's own state is still in its temporal dead zone.
    if (yomiScale !== previousScale) yomiScaleDirty = true

    sizeEditFrame(yomiDOM.getElementById("yomi-edit-frame"), force)
}

refreshYomiScale()
// Wrapped rather than passed by reference: a listener hands the Event in as the first argument,
// which would read as force=true on every one of them.
window.addEventListener("resize", () => refreshYomiScale())
window.addEventListener("orientationchange", () => refreshYomiScale(true))
// A pinch fires neither of the above: resize on visualViewport is the zoom, scroll is the pan
// that follows it, and both move the region the frame has to cover.
if (window.visualViewport) {
    window.visualViewport.addEventListener("resize", () => refreshYomiScale())
    window.visualViewport.addEventListener("scroll", () => refreshYomiScale())
}

window.yomiDOM = yomiDOM

yomiDOM.appendChild(yomiStyle)
yomiDOM.appendChild(tailwindStyle)
yomiDOM.appendChild(colorisStyle)

// --- Theme (dark mode) ---
// `.dark` goes on yomiOverlay (the shadow host) rather than inside yomiDOM: the
// `:host(.dark) &` clause in the extension's dark: custom variant (extension/css/main.css)
// is what lets tailwindStyle's rules, injected inside the shadow root above, react to it.
// Synced through api.storage.sync (set from the popup's theme toggle) instead of
// localStorage, since localStorage here would be scoped to whatever page Yomi is running on,
// not shared with the popup or other tabs.
const YOMI_THEME_KEY = "yomi_theme"
const YOMI_THEME_FORCED_DARK_ONCE_KEY = "yomi_theme_forced_dark_once"

function applyYomiTheme(theme) {
    const isDark = theme !== "light"
    yomiOverlay.classList.toggle("dark", isDark)
    yomiEditDoc?.documentElement.classList.toggle("dark", isDark)
}

api.storage.sync.get({ [YOMI_THEME_KEY]: null, [YOMI_THEME_FORCED_DARK_ONCE_KEY]: false }, (result) => {
    // One-time migration to dark-by-default, mirroring the website and the popup: whoever gets
    // here first (any tab, or the popup) sets it once, and it's respected from then on.
    if (!result[YOMI_THEME_FORCED_DARK_ONCE_KEY]) {
        api.storage.sync.set({ [YOMI_THEME_KEY]: "dark", [YOMI_THEME_FORCED_DARK_ONCE_KEY]: true })
        applyYomiTheme("dark")
    } else {
        applyYomiTheme(result[YOMI_THEME_KEY])
    }
})

api.storage.onChanged.addListener((changes, area) => {
    if (area === "sync" && changes[YOMI_THEME_KEY]) {
        applyYomiTheme(changes[YOMI_THEME_KEY].newValue)
    }
})

function injectOverlay() {
    const parent = document.documentElement || document.body
    if (parent && !parent.contains(yomiOverlay)) {
        parent.appendChild(yomiOverlay)
    }
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", injectOverlay)
} else {
    injectOverlay()
}

const yomiObserver = new MutationObserver(() => {
    const parent = document.documentElement || document.body
    if (parent && !parent.contains(yomiOverlay)) {
        parent.appendChild(yomiOverlay)
    }
})
if (document.documentElement) {
    yomiObserver.observe(document.documentElement, { childList: true })
} else {
    document.addEventListener("DOMContentLoaded", () => {
        yomiObserver.observe(document.documentElement, { childList: true })
    })
}


function injectYomiFonts() {
    const fontRegistry = [
        { name: "KomikaJam", file: "KomikaJam.ttf" },
        { name: "Bangers", file: "Bangers.woff2" },
        { name: "NotoSans", file: "NotoSans.woff2" },
        { name: "WildWords", file: "WildWords.otf" },
        { name: "Figtree", file: "Figtree.woff2" },
        { name: "Edo", file: "Edo.ttf" },
        { name: "RIDIBatang", file: "RIDIBatang.otf" },
        { name: "Bushidoo", file: "Bushidoo.ttf" },
        { name: "Hayah", file: "Hayah.otf" },
        { name: "Itim", file: "Itim.woff2" },
        { name: "MogulIrina", file: "MogulIrina.ttf" },
        { name: "BadComic", file: "BadComic.woff2" },
        { name: "MaShanZheng", file: "MaShanZheng.woff2" },
        { name: "Kalam", file: "Kalam.woff2" },
        { name: "HindSiliguri", file: "HindSiliguri.woff2" },
        { name: "Heroika", file: "Heroika.woff2" },
        { name: "Shonen", file: "Shonen.woff2" }
    ];

    let dynamicCSS = "";
    fontRegistry.forEach(font => {
        const secureUrl = api.runtime.getURL(`fonts/${font.file}`);
        dynamicCSS += `
            @font-face {
                font-family: "${font.name}";
                src: url("${secureUrl}");
            }
        `;
    });

    // Inject into main document
    const stylePage = document.createElement("style");
    stylePage.textContent = dynamicCSS;
    (document.head || document.documentElement).appendChild(stylePage);

    // Inject into Shadow DOM layer
    const styleShadow = document.createElement("style");
    styleShadow.textContent = dynamicCSS;
    yomiDOM.appendChild(styleShadow);
}

injectYomiFonts();

