        editDoc.getElementById("warp-preset-wave").firstElementChild.src = api.runtime.getURL("images/warp-wave.png")
        editDoc.getElementById("warp-preset-squeeze").firstElementChild.src = api.runtime.getURL("images/warp-squeeze.png")
        editDoc.getElementById("warp-preset-perspective").firstElementChild.src = api.runtime.getURL("images/warp-perspective.png")
        editDoc.getElementById("warp-preset-twist").firstElementChild.src = api.runtime.getURL("images/warp-twist.png")
